sys_script_include.script:
var MapperBase = Class.create();
MapperBase.prototype = {
	key: '',
	value:'',
	data:[],

    initialize: function(dataSourceName, key, value) {
		this.data_source_name = dataSourceName;
		this.key = key;
		this.value = value;
		this.data = fetch(dataSourceName);
    },

	fetch: function(dataSourceName){ 
		var data_source_sys_id = getDataSourceSysId(dataSourceName);
		var data = getMappedValues(data_source_sys_id);
		return data; 
	},

	getDataSourceSysId: function(dataSourceName){
		var result = '';
		var gr = new GlideRecord("sys_data_source");
		gr.addQuery("sys_scope", gs.getCurrentApplicationScope());
		gr.addQuery("name", dataSourceName);
		gr.setLimit(1);
		gr.query();
		if(gr.next()) result = gr.getValue("sys_id");
		return result;
	},

	getAttachmentSysId: function(dataSourceSysId) {
		var result = "";
		var gr = new GlideRecord("sys_attachment");
		gr.addQuery("table_name", "sys_data_source");
		gr.addQuery("table_sys_id", dataSourceSysId);
		gr.setLimit(1);
		gr.query();
		if (gr.next()) result = gr.getValue("sys_id");
		return result;
	},

	getMappedValues: function(dataSourceSysId) {
		var attachment_sys_id = getAttachmentSysId();

	},

    type: 'MapperBase'
};
